async function answerFrame(
  ws: WebSocket,
  session: ChatSession,
  validation: ValidationResult,
  sessionStore: SessionStore | undefined,
  options: MessageHandlerOptions
): Promise<void> {
  if (!validation.valid) {
    log.warn('message', 'validation failed', {error: validation.error});
    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
    return;
  }

  const message = validation.data;
  if (message.type === 'ping') handlePing(ws, message.timestamp);
  if (message.type === 'list_conversations') {
    if (!options.history?.enabled || sessionStore?.listFor === undefined) {
      sendError(ws, ErrorCodes.UNSUPPORTED, 'Conversation history is not available');
      return;
    }

    try {
      const summaries = await sessionStore.listFor(session.userId, {limit: message.limit, before: message.before});
      sendConversationList(ws, summaries);
    } catch (error) {
      log.error('ws', 'conversation list failed', {
        sessionId: session.sessionId,
        userId: session.userId,
        errorType: error instanceof Error ? error.constructor.name : typeof error,
      });
      sendError(
        ws,
        error instanceof StoreCannotList ? ErrorCodes.UNSUPPORTED : ErrorCodes.SERVER_ERROR,
        error instanceof StoreCannotList ? 'Conversation history is not available' : 'Failed to list conversations'
      );
    }
  }
import {validateMessage} from './validation.js';

// One wire name for the client frame: the alias is gone, and the frame the validator returns is the exported shape.

describe('the websocket frame validator', () => {
  it('accepts user_message and returns the frame the exported union describes', () => {
    const result = validateMessage({type: 'user_message', content: 'hello'});

    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });

  it('rejects send_message, which is no longer a wire name', () => {
    const result = validateMessage({type: 'send_message', content: 'hello'});

    expect(result).toEqual({valid: false, error: 'Unknown message type: send_message'});
  });

  it('drops any field the frame does not define, rather than forwarding it', () => {
    const result = validateMessage({type: 'user_message', content: 'hello', chatId: 'c1'});

    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });

  // spec: specs/hal-engine-conversation-list#3
  it('accepts list_conversations with an optional limit and cursor while ignoring userId', () => {
    const before = {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 's1'};

    const result = validateMessage({type: 'list_conversations', limit: 10, before, userId: 'another-user'});

    expect(result).toEqual({valid: true, data: {type: 'list_conversations', limit: 10, before}});
  });

  // spec: specs/hal-engine-conversation-list#3
  it('rejects malformed list_conversations pagination fields with field-specific errors', () => {
    const invalid = [
      [{type: 'list_conversations', limit: 0}, 'limit'],
      [{type: 'list_conversations', limit: 201}, 'limit'],
      [{type: 'list_conversations', limit: 1.5}, 'limit'],
      [{type: 'list_conversations', limit: '10'}, 'limit'],
      [{type: 'list_conversations', before: 'not a date'}, 'before'],
      [{type: 'list_conversations', before: {updatedAt: 'not a date', sessionId: 's1'}}, 'updatedAt'],
    ] as const;

    for (const [payload, field] of invalid) {
      const result = validateMessage(payload);

      expect(result).toEqual({valid: false, error: expect.stringContaining(field)});
    }
  });
});

